              "HS làm việc theo nhóm, trả lời và bổ sung:\n– Trường hợp a: Bạn Phống đã biết vượt qua khó khăn bằng cách chăm chỉ, kỉ luật với bản thân, hằng ngày thức dậy rất sớm để đi bộ đến trường đều đặn, đúng giờ.\n– Trường hợp b: Bạn Ngọc biết vượt khó, không ngại thử những điều mới, phức tạp. Điều đó sẽ giúp bạn học tốt môn cầu lông đồng thời có thể khám phá những khả năng của bản thân, thêm mạnh dạn, tự tin.\n– Trường hợp c: Bạn Phương không có tinh thần vượt khó, vừa gặp một chút khó khăn đã nản chí.\n– Trường hợp d: Hằng sợ khó nên đã từ chối khi bố muốn dạy bạn cách tỉa, tạo dáng cho cây cảnh, chứng tỏ bạn là người ngại khó, ngại khổ. Nếu cứ tiếp tục như vậy bạn sẽ trở nên thụ động, tự ti, không khai thác, khám phá được những khả năng của bản thân,..."
