              "– Trường hợp c: Bạn thường đi học trễ vì thói quen ngủ dậy muộn:\n+ Sắp xếp thời gian ngủ cố định theo lịch.\n+ Không sử dụng các thiết bị công nghệ ít nhất 30 phút trước khi đi ngủ;\n+ Tới các cơ sở y tế để được kiểm tra và có hướng can thiệp kịp thời nếu khó ngủ.\n– Trường hợp d: Bạn bị một nhóm bạn khác bắt nạt:\n+ Tìm sự giúp đỡ từ cha mẹ, người thân, bạn bè, thầy cô, gia đình.\n+ Tránh xa bạn xấu;\n+ Quản lí cảm xúc giận dữ."
